            AddSoundVolume("Sounds\\Effects\\thornhit.wav", tx, ty,  126, 1500.)

            DelayAction(0.439, function()
                ApplyEffect(caster, nil, tx, ty, "retribution_effect", 1, buff.ability_instance)
            end)


    end

