    function LightningFadeIn(lightning, faderate)
        local fade_time = faderate
        local timer = CreateTimer()
        faderate = 0.

            TimerStart(timer, 0.025, true, function()
                if faderate >= 1. then
                    SetLightningColor(lightning, 1., 1., 1., 1.)
                    PauseTimer(timer)
                    DestroyTimer(timer)
                else
                    SetLightningColor(lightning, 1., 1., 1., faderate / fade_time)
                    faderate = faderate + 0.025
                end
            end)
    end

    function LightningFadeOut(lightning, faderate)
        local fade_time = faderate
        local timer = CreateTimer()

            TimerStart(timer, 0.025, true, function()
                if faderate <= 0. then
                    DestroyLightning(lightning)
                    PauseTimer(timer)
                    DestroyTimer(timer)
                else
                    SetLightningColor(lightning, 1., 1., 1., faderate / fade_time)
                    faderate = faderate - 0.025
                end
            end)

    end

