    function ShieldThrowEffect(source, target, missile)

        if not missile.shield_targets then
            missile.shield_targets = 3
            missile.shield_sub_group = CreateGroup()
            GroupAddUnit(missile.shield_sub_group, target)
        end

         missile.shield_targets = missile.shield_targets - 1

            if missile.shield_targets <= 0 then
                missile.effect_on_hit = nil
                local a = AngleBetweenUnitXY(source, missile.current_x, missile.current_y) - 180.
                RedirectMissile_Deg(missile, a)
                --BlzSetSpecialEffectOrientation(missile.my_missile, a * bj_DEGTORAD, 0., 0.)
                BlzSetSpecialEffectYaw(missile.my_missile, a * bj_DEGTORAD)
                missile.time = DistanceBetweenUnitXY(source, missile.current_x, missile.current_y) / missile.speed
                DestroyGroup(missile.shield_sub_group)
            else
                local g = CreateGroup()
                local player = GetOwningPlayer(source)
                local final_target
                local a

                    GroupAddUnit(missile.shield_sub_group, target)
                    GroupEnumUnitsInRange(g, missile.current_x, missile.current_y, 600., nil)

                    for index = BlzGroupGetSize(g) - 1, 0, -1 do
                        local picked = BlzGroupUnitAt(g, index)

                        if IsUnitEnemy(picked, player) and GetUnitState(picked, UNIT_STATE_LIFE) > 0.045 and GetUnitAbilityLevel(picked, FourCC("Avul")) == 0 and not IsUnitInGroup(picked, missile.shield_sub_group) then
                            final_target = picked
                            break
                        end
                    end



                    if final_target then
                        a = AngleBetweenUnitXY(final_target, missile.current_x, missile.current_y) - 180.
                        RedirectMissile_Deg(missile, a)
                        BlzSetSpecialEffectYaw(missile.my_missile, a * bj_DEGTORAD)
                        missile.time = missile.max_distance / missile.speed
                    else
                        missile.effect_on_hit = nil
                        a = AngleBetweenUnitXY(source, missile.current_x, missile.current_y) - 180.
                        RedirectMissile_Deg(missile, a)
                        BlzSetSpecialEffectYaw(missile.my_missile, a * bj_DEGTORAD)
                        missile.time = DistanceBetweenUnitXY(source, missile.current_x, missile.current_y) / missile.speed
                        DestroyGroup(missile.shield_sub_group)
                    end

                    DestroyGroup(g)

            end
